/**
 * @param {number[]} nums
 * @return {number[]}
 */
var minBitwiseArray = function(nums) {
    let res = [];

    for (const num of nums) {
        let cur = -1;

        if (num % 2 === 0) {
            res.push(cur);
            continue;
        }

        const bin = num.toString(2);
        for (let i = 0; i < bin.length; i++) {
            if (bin[i] === '1') {
                const candidate = num - 2 ** (bin.length - 1 - i);

                if ((candidate | (candidate + 1)) === num) {
                    cur = candidate;
                    break;
                }
            }
        }

        res.push(cur);
    }

    return res;
};

//  3 -  011 ->  001
//  5 -  101 ->  100
//  7 -  111 ->  011
// 11 - 1011 -> 1001
